// Eventos automáticos de conciliação e solicitações manuais enviadas pela interface.
const evento = $input.first().json.body || {};
const d = evento.dados || {};
const status = d.status || 'PENDENTE';
if (!['analise_manual', 'conciliacao_atualizada'].includes(evento.evento)) return [];
if (!['MATCH', 'DIVERGENCIA', 'AGUARDANDO_FATURA', 'PAGO_PARCIAL', 'PENDENTE'].includes(status)) return [];
const nl = d.notaLancada || {};
const np = d.notaPaga || {};
const fatura = (d.fatura || {}).dados || {};
const tipos = { agencia: 'Agência', rodoviaria: 'Rodoviária', garagem: 'Garagem' };
const localNome = (d.local || {}).nome || nl.local_nome || nl.entidade_id || '';
const local = `${tipos[nl.entidade_tipo] || 'Local'} ${localNome}`.trim();
const brl = (v) => 'R$ ' + Number(v || 0).toFixed(2).replace('.', ',');
// Fase C: toda análise vai primeiro ao SIG (gerente); a SIE recebe só o que o gerente validar.
const escopo = 'SIG';
const rotulos = {
  MATCH: `Ciclo fechado · ${local} · NF ${nl.numero || nl.id}`,
  DIVERGENCIA: `Divergência · ${local} · NF ${nl.numero || nl.id}`,
  AGUARDANDO_FATURA: `Aguardando fatura · ${local} · NF ${nl.numero || nl.id}`,
  PAGO_PARCIAL: `Pagamento parcial · ${local} · NF ${nl.numero || nl.id}`,
  PENDENTE: `Análise pendente · ${local} · NF ${nl.numero || nl.id}`,
};
const titulo = `${evento.evento === 'analise_manual' ? 'Análise manual · ' : ''}${rotulos[status]}`;
const resumo = {
  chave: nl.chave || nl.id || '', numero: nl.numero || '', serie: nl.serie || '',
  localTipo: nl.entidade_tipo || '', localNome, localCidade: (d.local || {}).cidade || nl.local_cidade || '',
  local, provedor: nl.provedor_nome || '', emissao: nl.data_emissao || '', vencimento: nl.data_vencimento || '',
  valorLancado: Number(nl.valor_total || 0), valorPagoAcumulado: Number(d.valorPagoAcumulado || np.valor_pago || 0),
  dataPagamento: np.data_pagamento || '',
  fatura: d.fatura ? { id: d.fatura.id || d.fatura.fatura_id || "", valor: fatura.valorTotal, vencimento: fatura.dataVencimento, emissor: fatura.emissorNome } : null,
  comparacao: d.comparacao || {}, observacao: d.observacao || '',
  aceitaDivergencia: Boolean(d.aceitaDivergencia), origem: evento.evento,
};
const textoBase = [
  titulo,
  `Provedor: ${resumo.provedor || '-'} · Valor lançado: ${brl(resumo.valorLancado)} · Pago: ${brl(resumo.valorPagoAcumulado)}`,
  `Emissão ${resumo.emissao || '-'} · Vencimento ${resumo.vencimento || '-'} · Pagamento ${resumo.dataPagamento || '-'}`,
  resumo.fatura ? `Fatura: ${brl(resumo.fatura.valor)} · vencimento ${resumo.fatura.vencimento || '-'}` : 'Fatura: ainda não disponível',
  `Situação: ${resumo.observacao || status}${resumo.aceitaDivergencia ? ' · divergência aceita para análise manual, sem aprovação automática' : ''}`,
].join('\n');
const prompt = `Você apoia a gestão de custos de provedores de internet/telefonia de agências, rodoviárias e garagens.
Escreva em português do Brasil, em no máximo 6 linhas, ${escopo === 'SIE'
  ? 'um resumo executivo para a diretoria sobre este ciclo fechado (nota lançada, pagamento e fatura conferidos): custo, prazo de pagamento e qualquer ponto de atenção.'
  : 'uma análise gerencial explicando a pendência ou divergência abaixo e qual ação manual o time deve tomar.'}
Use só os dados fornecidos; não invente valores.
Dados: ${JSON.stringify(resumo)}`;
return [{ json: { escopo, status, titulo, referencia: nl.id || nl.chave || '', textoBase, prompt, dados: { ...resumo, status, requerValidacao: ['MATCH', 'DIVERGENCIA'].includes(status), etapa: 'gerente' } } }];

const base = $input.first().json;
const event = $('Eventos da API SIGp').first().json.body || {};
const d = event.dados || {};
const nl = d.notaLancada || {};
const invoice = (d.fatura || {}).dados || {};
const descriptions = [
  ...(Array.isArray(nl.servicos) ? nl.servicos.map((service) => service.descricao) : []),
  nl.descricao,
  invoice.descricao,
  invoice.descricaoServico,
  invoice.servico,
].map((value) => String(value || '').trim()).filter(Boolean);
const rawAmount = invoice.valorTotal;
const rawAmountText = String(rawAmount ?? '').trim();
const normalizedAmount = rawAmountText.includes(',')
  ? rawAmountText.replace(/[.]/g, '').replace(',', '.')
  : rawAmountText;
const amount = rawAmountText ? Number(normalizedAmount) : NaN;
const aiInvoice = {
  provider: String(invoice.emissorNome || nl.provedor_nome || '').trim().slice(0, 80),
  description: [...new Set(descriptions)].join('; ').slice(0, 1000),
  amount,
  due_date: String(invoice.dataVencimento || nl.data_vencimento || '').trim(),
};
const aiEligible = Boolean(d.fatura)
  && Boolean(aiInvoice.provider)
  && Boolean(aiInvoice.description)
  && Number.isFinite(aiInvoice.amount)
  && aiInvoice.amount >= 0;
const aiSkipReason = !d.fatura
  ? 'Fatura ainda não disponível.'
  : !aiInvoice.provider
    ? 'Provedor não identificado na fatura ou nota.'
    : !aiInvoice.description
      ? 'Descrição de serviço não identificada.'
      : !Number.isFinite(aiInvoice.amount) || aiInvoice.amount < 0
        ? 'Valor da fatura não identificado ou inválido.'
        : '';
return [{ json: { ...base, aiInvoice, aiEligible, aiSkipReason } }];

const base = $('Preparar entrada acadêmica').first().json;
const input = $input.first().json || {};
const result = input.body && typeof input.body === 'object' ? input.body : input;
const classification = ['CONTRATADO', 'DIVERGENTE', 'REVISAR'].includes(result.classification)
  ? result.classification
  : '';
const modelClassification = ['CONTRATADO', 'DIVERGENTE', 'REVISAR'].includes(result.model_classification)
  ? result.model_classification
  : '';
const generated = result.ok === true && classification && modelClassification;
const failure = input.error?.message || result.error || result.message || 'A API acadêmica não retornou um parecer válido.';
const parecerIA = generated
  ? {
      status: 'gerado',
      classification,
      reason: String(result.reason || ''),
      model_classification: modelClassification,
      model_agreement: result.model_agreement === true,
      model_is_authoritative: false,
      model: String(result.model || ''),
      model_profile: String(result.model_profile || ''),
      prompt_version: String(result.prompt_version || ''),
      prompt_sha256: String(result.prompt_sha256 || ''),
      source_ids: Array.isArray(result.source_ids) ? result.source_ids : [],
      correlation_id: String(result.correlation_id || ''),
      latency_ms: Number(result.latency_ms || 0),
      aviso: 'Corpus acadêmico demonstrativo; não valida contratos reais e não altera conciliação ou pagamento.',
    }
  : {
      status: base.aiEligible ? 'nao_gerado' : 'sem_dados',
      reason: String(base.aiSkipReason || failure).slice(0, 300),
      model_is_authoritative: false,
      aviso: 'A análise determinística do SIGp permanece inalterada.',
    };
const linhasParecer = generated
  ? [
      '',
      'Parecer experimental RAG/Qwen (não autoritativo):',
      `Classificação estruturada acadêmica: ${classification}.`,
      `Classificação proposta pelo modelo: ${modelClassification}.`,
      `Motivo: ${parecerIA.reason || 'não informado pela API acadêmica'}`,
      `Fontes demonstrativas: ${parecerIA.source_ids.join(', ') || 'nenhuma'}.`,
      parecerIA.aviso,
    ]
  : [
      '',
      `Parecer experimental RAG/Qwen não gerado: ${parecerIA.reason}`,
      parecerIA.aviso,
    ];
const conteudo = `${base.textoBase}\n${linhasParecer.join('\n')}`;
const modelo = generated
  ? `SIGp determinístico + Qwen experimental (${parecerIA.model_profile || parecerIA.model || 'perfil não informado'})`
  : 'SIGp determinístico; parecer Qwen não gerado';
return [{ json: {
  ...base,
  dados: { ...base.dados, parecerIA },
  conteudo,
  modelo,
} }];

// Notifica ciclos fechados e divergências a partir do que foi gravado (já com a análise da LLM).
const r = $input.first().json || {};
const item = (r.body || r).item || {};
if (!['MATCH', 'DIVERGENCIA'].includes((item.dados || {}).status)) return [];
return [{ json: { assunto: `SIGp · ${item.titulo}`, texto: `${item.titulo}\n\n${item.conteudo}` } }];

// A LLM local analisa os ciclos fechados (MATCH = 3 evidências) e as divergências (D14). Os demais status
// seguem com o texto da regra. A regra do SIGp continua sendo a decisão oficial (D13).
const base = $input.first().json;
const precisaLLM = ['MATCH', 'DIVERGENCIA'].includes(base.status);
const { parecerIA, ...dadosDoCiclo } = base.dados || {};
// Fatos calculados aqui (a LLM pequena erra contas de data e valor): ela só redige a partir deles.
const brl = (v) => 'R$ ' + Number(v || 0).toFixed(2).replace('.', ',');
const dataBR = (iso) => (/^\d{4}-\d{2}-\d{2}/.test(String(iso || '')) ? String(iso).slice(0, 10).split('-').reverse().join('/') : 'não informado');
const dias = (a, b) => Math.round((Date.parse(String(a).slice(0, 10)) - Date.parse(String(b).slice(0, 10))) / 86400000);
const fatos = [];
const lancado = Number(dadosDoCiclo.valorLancado || 0);
const pago = Number(dadosDoCiclo.valorPagoAcumulado || 0);
const valorFatura = Number(dadosDoCiclo.fatura?.valor || 0);
fatos.push(`Valor lançado: ${brl(lancado)}. Valor pago: ${pago ? brl(pago) : 'nenhum pagamento'}.`
  + (pago ? (Math.abs(lancado - pago) < 0.01 ? ' Pago igual ao lançado.' : ` Diferença: ${brl(pago - lancado)} (${pago < lancado ? 'pago a menos' : 'pago a mais'}).`) : ''));
fatos.push(dadosDoCiclo.fatura
  ? `Fatura: ${brl(valorFatura)}, vencimento ${dataBR(dadosDoCiclo.fatura.vencimento)}.` + (Math.abs(valorFatura - lancado) < 0.01 ? ' Fatura igual ao lançado.' : ` Diferença fatura x lançado: ${brl(valorFatura - lancado)}.`)
  : 'Fatura: ainda não disponível.');
if (dadosDoCiclo.dataPagamento && dadosDoCiclo.vencimento) {
  const d = dias(dadosDoCiclo.dataPagamento, dadosDoCiclo.vencimento);
  fatos.push(`Pagamento em ${dataBR(dadosDoCiclo.dataPagamento)}, vencimento em ${dataBR(dadosDoCiclo.vencimento)}: `
    + (d === 0 ? 'pago no dia do vencimento (no prazo).' : d < 0 ? `pago ${-d} dia(s) ANTES do vencimento (no prazo).` : `pago ${d} dia(s) DEPOIS do vencimento (em atraso).`));
} else {
  fatos.push(`Vencimento: ${dataBR(dadosDoCiclo.vencimento)}. Data de pagamento: não informada.`);
}
if (dadosDoCiclo.fatura && dadosDoCiclo.fatura.emissor && dadosDoCiclo.provedor) fatos.push(`Provedor da nota: ${dadosDoCiclo.provedor}. Emissor da fatura: ${dadosDoCiclo.fatura.emissor}.`);
if (dadosDoCiclo.observacao) fatos.push(`Observação da regra: ${dadosDoCiclo.observacao}`);
const usuario = [
  `Status calculado pela regra do sistema (oficial): ${base.status}`,
  `Local: ${dadosDoCiclo.local || dadosDoCiclo.localNome || 'não informado'}. Nota: ${dadosDoCiclo.numero || 'não informada'}.`,
  'FATOS CALCULADOS (corretos; use exatamente estes, não refaça contas):',
  ...fatos.map((f) => `- ${f}`),
].join('\n');
const ollamaBody = {
  model: $env.SIGP_OLLAMA_MODEL || 'qwen2.5:3b',
  stream: false,
  options: { temperature: 0, num_ctx: 4096 },
  format: {"type": "object", "properties": {"conclusao": {"type": "string", "enum": ["confere", "diverge", "revisar"]}, "resumo": {"type": "string"}, "pontosDeAtencao": {"type": "array", "items": {"type": "string"}}, "acaoSugerida": {"type": "string"}, "confianca": {"type": "number"}}, "required": ["conclusao", "resumo", "pontosDeAtencao", "acaoSugerida", "confianca"]},
  messages: [
    { role: 'system', content: "Você é o analista de contas de internet de um grupo de transporte rodoviário (agências, rodoviárias e garagens).\nEscreva para o GERENTE, em português do Brasil, com frases curtas, claras e profissionais.\n\nRegras de linguagem:\n- Use somente os dados fornecidos. Nunca invente valores, datas, nomes ou números de nota.\n- Valores em reais com vírgula: R$ 119,90. Datas no formato dd/mm/aaaa.\n- Dado ausente: escreva \"não informado\".\n- Termos: \"nota lançada\" (registrada para pagamento), \"nota paga\" (pagamento confirmado), \"fatura\" (PDF do provedor), \"ciclo fechado\" (as três conferem), \"competência\" (mês da cobrança).\n- Sem jargão técnico, sem inglês, sem emojis.\n\nRegras de fidelidade:\n- Os FATOS CALCULADOS estão corretos: copie números, datas e prazos deles; nunca refaça contas.\n- Só aponte um problema se ele estiver nos fatos. Não suponha erros que os fatos não mostram.\n\nRegras de decisão:\n- O STATUS calculado pela regra do sistema é a decisão oficial. Você analisa, explica e aponta riscos; não muda o status.\n- conclusao = \"confere\" quando lançado, pago e fatura batem em valor, vencimento, provedor e local.\n- conclusao = \"diverge\" quando há diferença em valor, vencimento, provedor, local ou serviço.\n- conclusao = \"revisar\" quando faltam dados para concluir.\n- resumo: no máximo 3 frases, começando pelo que importa (confere ou não, e por quê).\n- pontosDeAtencao: até 4 itens curtos e concretos (ex.: \"Pago 2 dias após o vencimento.\"). Lista vazia se não houver.\n- acaoSugerida: uma frase com a próxima ação do gerente (ex.: \"Validar o ciclo.\" ou \"Pedir a fatura corrigida ao provedor.\").\n- confianca: de 0 a 1, sua certeza na conclusão.\nResponda somente com o JSON do schema." },
    { role: 'user', content: usuario },
  ],
};
return [{ json: { ...base, precisaLLM, ollamaBody } }];

const base = $('Preparar pedido à LLM (SIG)').first().json;
const resposta = $input.first().json || {};
const ROTULO = { confere: 'confere', diverge: 'diverge', revisar: 'precisa de revisão' };
let llm = null;
let erro = '';
try {
  const conteudo = JSON.parse(resposta.message?.content || '');
  if (!ROTULO[conteudo.conclusao] || !String(conteudo.resumo || '').trim()) throw new Error('resposta fora do formato');
  llm = conteudo;
} catch (e) {
  erro = String(resposta.error?.message || resposta.error || e.message || 'sem resposta do Ollama').slice(0, 300);
}
const { ollamaBody, precisaLLM, ...resto } = base;
if (!llm) {
  // Sem LLM (fora do ar, lenta ou resposta inválida): grava a análise da regra e registra o motivo.
  return [{ json: { ...resto, dados: { ...resto.dados, analiseLLM: { status: 'nao_gerada', motivo: erro } } } }];
}
const discorda = (base.status === 'MATCH' && llm.conclusao !== 'confere')
  || (base.status === 'DIVERGENCIA' && llm.conclusao === 'confere');
const linhas = [
  `Análise da LLM local: ${ROTULO[llm.conclusao]}.`,
  String(llm.resumo).trim(),
  ...(Array.isArray(llm.pontosDeAtencao) ? llm.pontosDeAtencao : []).slice(0, 4).map((p) => `• ${String(p).trim()}`),
  llm.acaoSugerida ? `Ação sugerida: ${String(llm.acaoSugerida).trim()}` : null,
  discorda ? `Atenção: a LLM discorda da regra do sistema (${base.status}). O status oficial é o da regra; confira antes de validar.` : null,
  '',
  'Dados do sistema:',
  String(resto.conteudo || ''),
].filter((linha) => linha !== null);
return [{ json: {
  ...resto,
  conteudo: linhas.join('\n'),
  modelo: `LLM local ${ollamaBody.model} + regra do SIGp`,
  dados: { ...resto.dados, analiseLLM: { status: 'gerada', ...llm, discordaDaRegra: discorda, modelo: ollamaBody.model } },
} }];

// Decisão do gerente (evento "decisao_gerente" enviado pelo SIGp). Só VALIDADA ou CORRIGIDA seguem para a SIE.
const evento = $input.first().json.body || {};
if (evento.evento !== 'decisao_gerente') return [];
const dados = evento.dados || {};
const decisao = dados.decisao || {};
const analise = dados.analise || {};
if (!['VALIDADA', 'CORRIGIDA'].includes(decisao.status)) return [];
const textoValidado = decisao.status === 'CORRIGIDA' && decisao.conteudo_corrigido ? decisao.conteudo_corrigido : analise.conteudo;
const { analiseLLM, parecerIA, ...resumo } = dados.resumo || {};
const brl = (v) => 'R$ ' + Number(v || 0).toFixed(2).replace('.', ',');
const dataBR = (iso) => (/^\d{4}-\d{2}-\d{2}/.test(String(iso || '')) ? String(iso).slice(0, 10).split('-').reverse().join('/') : 'não informado');
const diasPag = resumo.dataPagamento && resumo.vencimento
  ? Math.round((Date.parse(String(resumo.dataPagamento).slice(0, 10)) - Date.parse(String(resumo.vencimento).slice(0, 10))) / 86400000)
  : null;
const fatos = [
  `Local: ${resumo.local || resumo.localNome || 'não informado'}. Provedor: ${resumo.provedor || 'não informado'}.`,
  `Custo do ciclo (valor lançado): ${brl(resumo.valorLancado)}. Pago: ${brl(resumo.valorPagoAcumulado)}.`,
  diasPag === null ? 'Prazo: não informado.'
    : diasPag <= 0 ? `Prazo: pago no prazo (${diasPag === 0 ? 'no dia do vencimento' : `${-diasPag} dia(s) antes`}, vencimento ${dataBR(resumo.vencimento)}).`
      : `Prazo: pago com ${diasPag} dia(s) de atraso (vencimento ${dataBR(resumo.vencimento)}).`,
];
const usuario = [
  'FATOS CALCULADOS (corretos; use exatamente estes, não refaça contas):',
  ...fatos.map((f) => `- ${f}`),
  '',
  `Decisão do gerente: ${decisao.status === 'CORRIGIDA' ? 'validada com correção' : 'validada'} por ${decisao.usuario || 'gerente'}`
    + (decisao.justificativa ? ` (motivo: ${decisao.justificativa})` : ''),
  '',
  'Análise validada pelo gerente:',
  String(textoValidado || '').split('\nDados do sistema:')[0].trim(),
].join('\n');
const ollamaBody = {
  model: $env.SIGP_OLLAMA_MODEL || 'qwen2.5:3b',
  stream: false,
  options: { temperature: 0, num_ctx: 4096 },
  format: {"type": "object", "properties": {"resumoExecutivo": {"type": "string"}, "impacto": {"type": "string", "enum": ["nenhum", "baixo", "medio", "alto"]}, "recomendacao": {"type": "string"}}, "required": ["resumoExecutivo", "impacto", "recomendacao"]},
  messages: [
    { role: 'system', content: "Você redige o RESUMO EXECUTIVO para a diretoria de um grupo de transporte rodoviário, sobre os custos de internet\nde agências, rodoviárias e garagens. A análise abaixo já foi VALIDADA pelo gerente.\nEscreva em português do Brasil, tom executivo: direto, sem detalhes operacionais, sem jargão, sem emojis.\n\nRegras:\n- Use somente os FATOS CALCULADOS e a análise validada; copie valores e prazos dos fatos, nunca refaça contas.\n- Sempre cite o custo do ciclo em reais.\n- Se o gerente corrigiu a análise, a versão corrigida é a correta.\n- Valores em reais com vírgula (R$ 119,90); datas dd/mm/aaaa.\n- resumoExecutivo: 2 a 4 frases. Diga o local e o provedor, o custo do ciclo, se foi pago no prazo e o principal ponto de atenção, se houver.\n- impacto: \"nenhum\", \"baixo\", \"medio\" ou \"alto\" (risco financeiro ou operacional para a empresa).\n- recomendacao: uma frase para a diretoria (pode ser \"Nenhuma ação necessária.\").\nResponda somente com o JSON do schema." },
    { role: 'user', content: usuario },
  ],
};
return [{ json: {
  titulo: String(analise.titulo || 'Ciclo').replace(/^Análise manual · /, ''),
  referencia: analise.referencia || '',
  analiseOrigemId: analise.id || '',
  decisao,
  resumo,
  textoValidado,
  ollamaBody,
} }];

const base = $('Montar etapa executiva').first().json;
const resposta = $input.first().json || {};
let llm = null;
let erro = '';
try {
  const conteudo = JSON.parse(resposta.message?.content || '');
  if (!String(conteudo.resumoExecutivo || '').trim()) throw new Error('resposta fora do formato');
  llm = conteudo;
} catch (e) {
  erro = String(resposta.error?.message || resposta.error || e.message || 'sem resposta do Ollama').slice(0, 300);
}
const IMPACTO = { nenhum: 'nenhum', baixo: 'baixo', medio: 'médio', alto: 'alto' };
const validacao = `Validado por ${base.decisao.usuario || 'gerente'} em ${new Date(base.decisao.created_at || Date.now()).toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' })}`
  + (base.decisao.status === 'CORRIGIDA' ? ' (com correção)' : '') + '.';
const conteudo = llm
  ? [String(llm.resumoExecutivo).trim(), `Impacto: ${IMPACTO[llm.impacto] || 'não informado'}.`,
     llm.recomendacao ? `Recomendação: ${String(llm.recomendacao).trim()}` : '', validacao].filter(Boolean).join('\n')
  : [String(base.textoValidado || '').trim(), validacao].join('\n\n');
return [{ json: {
  escopo: 'SIE',
  titulo: base.titulo,
  referencia: base.referencia,
  conteudo,
  modelo: llm ? `LLM local ${base.ollamaBody.model}` : 'Análise validada pelo gerente (LLM indisponível)',
  dados: {
    ...base.resumo,
    analiseOrigemId: base.analiseOrigemId,
    decisaoGerente: base.decisao,
    resumoExecutivoLLM: llm ? { status: 'gerado', ...llm } : { status: 'nao_gerado', motivo: erro },
  },
} }];
